			buf.Reset()
		}
	}
	for i < len(path) {
		c := path[i]
		switch c {
		case '.':
			flushKey()
			i++
		case '[':
			flushKey()
			j := strings.IndexByte(path[i:], ']')
			if j < 0 { // malformed, treat rest as key?
