	m := New(nil)
	m.Set("a.b.c", 1).Set("a.b.d", 2).Set("items[]", "x").Set("items[]", "y")
	if got := m.Get("a.b.c").Int(); got != 1 {
		t.Fatalf("c = %d", got)
	}
	if got := m.Get("a.b.d").Int(); got != 2 {
		t.Fatalf("d = %d", got)
	}
	want := []interface{}{"x", "y"}
	if got := m.Get("items").Slice(); !reflect.DeepEqual(got, want) {
		t.Fatalf("items = %#v", got)
	}
